import { useId } from "react";
import "./AppIcon.css";

// Apple's app-icon outline is a superellipse, not a rounded rectangle.
const SQUIRCLE = (() => {
  const n = 5;
  const pts = [];
  for (let i = 0; i < 96; i++) {
    const t = (i / 96) * Math.PI * 2;
    const c = Math.cos(t);
    const s = Math.sin(t);
    const x = 50 + 50 * Math.sign(c) * Math.abs(c) ** (2 / n);
    const y = 50 + 50 * Math.sign(s) * Math.abs(s) ** (2 / n);
    pts.push(`${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return `M${pts.join("L")}Z`;
})();

export const TONES = {
  blue: ["#6ac4ff", "#0a6cff"],
  mail: ["#5ecbff", "#1778f2"],
  indigo: ["#8f8cff", "#4b3fe3"],
  discord: ["#8e97ff", "#5865f2"],
  purple: ["#d78bff", "#8e3ff0"],
  pink: ["#ff8fb8", "#ff2d6f"],
  orange: ["#ffc15c", "#ff6a14"],
  yellow: ["#ffe36b", "#f7b500"],
  green: ["#6fe38c", "#1faa4a"],
  teal: ["#6ee7e0", "#0a9fb5"],
  graphite: ["#5b5b62", "#1c1c1f"],
  silver: ["#ffffff", "#d9d9de"],
};

function AppIcon({ tone = "blue", size = 48, children, label, className = "", style }) {
  const id = useId().replace(/:/g, "");
  const [top, bottom] = TONES[tone] || tone;
  const light = tone === "silver";

  return (
    <span
      className={`app-icon ${light ? "is-light" : ""} ${className}`}
      style={{ "--icon": `${size}px`, ...style }}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : "true"}
    >
      <svg viewBox="0 0 100 100" aria-hidden="true">
        <defs>
          <linearGradient id={`g${id}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={top} />
            <stop offset="1" stopColor={bottom} />
          </linearGradient>
          <radialGradient id={`s${id}`} cx="50%" cy="0%" r="75%">
            <stop offset="0" stopColor="#fff" stopOpacity={light ? 0 : 0.42} />
            <stop offset="1" stopColor="#fff" stopOpacity="0" />
          </radialGradient>
          <clipPath id={`c${id}`}>
            <path d={SQUIRCLE} />
          </clipPath>
        </defs>
        <g clipPath={`url(#c${id})`}>
          <rect width="100" height="100" fill={`url(#g${id})`} />
          <rect width="100" height="58" fill={`url(#s${id})`} />
        </g>
        <path d={SQUIRCLE} fill="none" stroke={light ? "rgba(0,0,0,.08)" : "rgba(255,255,255,.22)"} strokeWidth="1.2" />
      </svg>
      <span className="app-icon-glyph">{children}</span>
    </span>
  );
}

export default AppIcon;
