import { useEffect, useRef } from "react";
import Button from "../Button";
import Statement from "../Statement";
import { InlineClip } from "../Inline";
import { PROFILE, STATUS } from "../../data/profile";
import useLocalTime from "../../hooks/useLocalTime";
import { Roll } from "../motion";
import { prefersReducedMotion } from "../../routes";

import "./Hero.css";

const CLIPS = {
  pumpkin: <InlineClip clip="pumpkin" project="pumpkinclick" />,
  kart: <InlineClip clip="kart" project="kartsystem" />,
  scan: <InlineClip clip="scan" project="scangame" />,
};

const GRID = 22;
const SPOT = 380;

function usePointerLight(sectionRef, spotRef) {
  useEffect(() => {
    const section = sectionRef.current;
    const spot = spotRef.current;
    if (!section || !spot) return undefined;

    const fine = window.matchMedia?.("(hover: hover) and (pointer: fine)").matches;
    if (!fine || prefersReducedMotion()) return undefined;

    let rect = null;
    let frame = 0;
    const target = { sx: 0, sy: 0 };
    const current = { sx: 0, sy: 0 };

    const measure = () => {
      rect = section.getBoundingClientRect();
    };

    const tick = () => {
      current.sx += (target.sx - current.sx) * 0.28;
      current.sy += (target.sy - current.sy) * 0.28;

      const left = current.sx - SPOT / 2;
      const top = current.sy - SPOT / 2;
      spot.style.transform = `translate3d(${left}px, ${top}px, 0)`;
      spot.style.backgroundPosition = `${-(left % GRID)}px ${-(top % GRID)}px`;

      const settling =
        Math.abs(target.sx - current.sx) > 0.3 ||
        Math.abs(target.sy - current.sy) > 0.3;

      frame = settling ? requestAnimationFrame(tick) : 0;
    };

    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(tick);
    };

    const onEnter = (e) => {
      measure();
      current.sx = target.sx = e.clientX - rect.left;
      current.sy = target.sy = e.clientY - rect.top;
      section.classList.add("is-pointing");
      schedule();
    };

    const onMove = (e) => {
      if (!rect) measure();
      target.sx = e.clientX - rect.left;
      target.sy = e.clientY - rect.top;
      schedule();
    };

    const onLeave = () => {
      section.classList.remove("is-pointing");
    };

    const invalidate = () => {
      rect = null;
    };

    section.addEventListener("pointerenter", onEnter);
    section.addEventListener("pointermove", onMove, { passive: true });
    section.addEventListener("pointerleave", onLeave);
    window.addEventListener("scroll", invalidate, { passive: true });
    window.addEventListener("resize", invalidate);

    return () => {
      cancelAnimationFrame(frame);
      section.removeEventListener("pointerenter", onEnter);
      section.removeEventListener("pointermove", onMove);
      section.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("scroll", invalidate);
      window.removeEventListener("resize", invalidate);
    };
  }, [sectionRef, spotRef]);
}

function Hero() {
  const sectionRef = useRef(null);
  const spotRef = useRef(null);
  const { time } = useLocalTime(PROFILE.timeZone);

  usePointerLight(sectionRef, spotRef);

  return (
    <section className="hero" id="top" data-nav-section="home" ref={sectionRef}>
      <div className="hero-field" aria-hidden="true">
        <div className="hero-dots" />
        <div className="hero-spot" ref={spotRef} />
      </div>

      <div className="shell hero-inner">
        <p className="hero-status" data-reveal>
          <span className={`status-dot ${STATUS.state === "busy" ? "is-busy" : ""}`} aria-hidden="true" />
          <span>
            {STATUS.label} {STATUS.detail}
          </span>
          <span className="hero-status-sep" aria-hidden="true" />
          <span className="hero-status-time">
            <Roll value={time} /> in {PROFILE.location}
          </span>
        </p>

        <Statement
          as="h1"
          size="xl"
          lit={false}
          className="hero-statement"
          lead="Hi, I'm Drxck."
          text="I build {pumpkin} Roblox games, {kart} gameplay systems and {scan} experiments that feel good to play."
          media={CLIPS}
        />

        <p className="hero-sub body-l" data-reveal>
          {PROFILE.role} based in {PROFILE.location}. {PROFILE.tagline}
        </p>

        <div className="hero-actions" data-reveal>
          <Button variant="primary" size="lg" href="#work">
            See the work
          </Button>
          <Button size="lg" href="#contact">
            Get in touch
          </Button>
        </div>
      </div>
    </section>
  );
}

export default Hero;
