import Button from "../Button";
import TransitionLink from "../TransitionLink";
import ProjectFolder from "./ProjectFolder";
import { FEATURED, PROJECTS } from "../../data/projects";
import { loadWork, prefetchWork } from "../../routes";
import Statement from "../Statement";
import { InlineClip } from "../Inline";
import "./WorkSection.css";

// The home folder shrinks into the folder icon in the Work page header.
const folderToHeader = () => [[document.querySelector(".home-work .folder-body"), "work-folder"]];

function WorkSection() {
  return (
    <section id="work" className="section home-work" data-nav-section="work">
      <div className="shell home-work-grid">
        <div className="home-work-copy" data-reveal>
          <Statement
            size="m"
            lead="Things I've built."
            text="Shipped games, {egg} gameplay systems and prototypes. Some for clients, some just to find out whether an idea works."
            media={{ egg: <InlineClip clip="egg" project="crackanegg" /> }}
          />

          <Button
            as={TransitionLink}
            to="/work"
            prepare={loadWork}
            pairs={folderToHeader}
            onPointerEnter={prefetchWork}
            onFocus={prefetchWork}
          >
            Browse my recent projects
          </Button>
        </div>

        <div className="home-work-stage" data-reveal style={{ "--reveal-delay": "80ms" }}>
          <ProjectFolder projects={FEATURED} total={PROJECTS.length} />
        </div>
      </div>
    </section>
  );
}

export default WorkSection;
