import { cloneElement, useEffect, useRef } from "react";
import { prefersReducedMotion } from "../routes";
import "./Statement.css";

// Words light up from grey to full colour as the statement scrolls through the viewport.
function useScrollLit(ref, enabled) {
  useEffect(() => {
    const el = ref.current;
    if (!el || !enabled) return undefined;
    const words = Array.from(el.querySelectorAll(".st-word"));
    if (!words.length) return undefined;

    if (prefersReducedMotion() || typeof IntersectionObserver === "undefined") {
      words.forEach((w) => w.style.setProperty("--lit", "1"));
      return undefined;
    }

    const SOFT = 4; // how many words the lit edge fades across
    let frame = 0;
    const last = new Array(words.length).fill(-1);

    const paint = () => {
      frame = 0;
      const box = el.getBoundingClientRect();
      const vh = window.innerHeight;
      const p = Math.min(1, Math.max(0, (vh * 0.88 - box.top) / (box.height + vh * 0.38)));
      const head = p * (words.length + SOFT);
      words.forEach((w, i) => {
        const lit = Math.min(1, Math.max(0, (head - i) / SOFT));
        const rounded = Math.round(lit * 50) / 50;
        if (rounded !== last[i]) {
          last[i] = rounded;
          w.style.setProperty("--lit", rounded);
        }
      });
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(paint);
    };

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        window.addEventListener("scroll", schedule, { passive: true });
        window.addEventListener("resize", schedule);
        schedule();
      } else {
        window.removeEventListener("scroll", schedule);
        window.removeEventListener("resize", schedule);
        paint();
      }
    });
    observer.observe(el);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
    };
  }, [ref, enabled]);
}

const split = (text) => (text ? text.split(/\s+/).filter(Boolean) : []);

/**
 * The site's headline voice: a bright lead, then a grey continuation.
 * `text` may hold {placeholders} filled from `media` (clips, photos, icons);
 * each one stays on the same line as the word after it.
 */
function Statement({ as: Tag = "h2", lead, text, media = {}, size = "l", lit = true, className = "", ...rest }) {
  const ref = useRef(null);
  useScrollLit(ref, lit);

  const leadWords = split(lead);
  const tokens = split(text);
  const spoken = [lead, tokens.filter((t) => !/^\{\w+\}$/.test(t)).join(" ")].filter(Boolean).join(" ");

  let w = 0;
  const word = (content, kind) => (
    <span aria-hidden="true" className={`rt-w ${kind}`} style={{ "--w": w++ }}>
      {content}
    </span>
  );

  const out = leadWords.map((t, i) => (
    <span key={`l${i}`}>
      {word(t, "st-lead")}{" "}
    </span>
  ));

  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    const key = /^\{(\w+)\}$/.exec(t)?.[1];
    const gap = i < tokens.length - 1 ? " " : null;
    if (key && media[key]) {
      const chip = cloneElement(media[key], { index: w++ });
      const next = tokens[i + 1];
      i += 1;
      out.push(
        <span key={`m${i}`}>
          <span className="st-bind">
            {chip} {next ? word(next, "st-word") : null}
          </span>
          {i < tokens.length - 1 ? " " : null}
        </span>
      );
      continue;
    }
    out.push(
      <span key={`t${i}`}>
        {word(t, "st-word")}
        {gap}
      </span>
    );
  }

  return (
    <Tag
      ref={ref}
      className={`statement is-${size} ${lit ? "is-lit" : ""} ${className}`}
      data-reveal="text"
      {...rest}
    >
      <span className="sr-only">{spoken}</span>
      {out}
    </Tag>
  );
}

export default Statement;
