import { forwardRef } from "react";
import { ArrowRight } from "lucide-react";

/**
 * Pill button with a round arrow chip. On hover the chip grows to fill the pill
 * and its arrow rolls through. The button itself never moves while hovered.
 */
const Button = forwardRef(function Button(
  { as: As = "a", variant = "secondary", size, icon: Icon = ArrowRight, children, className = "", ...rest },
  ref
) {
  return (
    <As
      ref={ref}
      className={`btn btn-${variant} ${size ? `btn-${size}` : ""} ${className}`}
      {...rest}
    >
      <span className="btn-fill" aria-hidden="true" />
      <span className="btn-label">{children}</span>
      <span className="btn-chip" aria-hidden="true">
        <Icon className="btn-arrow is-out" strokeWidth={2.4} />
        <Icon className="btn-arrow is-in" strokeWidth={2.4} />
      </span>
    </As>
  );
});

export default Button;
